import {mainNavigation} from './navigation.js';
import {surfaceTheme} from './styles/theme.js';
export async function mountWorkshopView({container:app,controller,initialKind='prompt',availability=()=>({memory:true,time:true,workshop:true,prompt:true,collect:true,sync:true})}) {
const lifetime=new AbortController();let acting=false,disposed=false,lastError='';
const toggleIntents=new Map();let toggleVersion=0;
let initial=await controller.load(),modules=initial.modules,results=initial.results;
const apply=value=>{lastError='';initial=value;modules=value.modules.map(module=>({...module,...(toggleIntents.has(module.id)?{enabled:toggleIntents.get(module.id).enabled}:{})}));results=value.results;};
const kinds={prompt:'提示词注入',collect:'内容收集',sync:'长期追踪'};
const scopes={global:'全局',character:'当前角色',chat:'当前聊天'};
const generationSources={story:'随剧情生成',background:'后台生成'};
const make=(id,kind,scope,name,content,enabled=true)=>({id,kind,scope,name,content,enabled,role:'system',depth:0,generationSource:'story'});
let state={kind:availability()[initialKind]&&Object.hasOwn(kinds,initialKind)?initialKind:Object.keys(kinds).find(key=>availability()[key])??'prompt',route:'root',theme:surfaceTheme(app),draft:null,moduleId:null,index:0,dialog:null,closed:false,query:'',directoryLimit:20};
let toastTimer,draftBaseline='';const scrolls={},collapsed={};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,attrs='',tone='tertiary')=>`<button type="button" class="ui-button ui-button--${tone}" data-action="${action}" ${initial.writeBlocked&&['save','delete-module','delete-result'].includes(action)?'disabled':''} ${attrs}>${text}</button>`;
const icon=(text,action,file,attrs='')=>`<button type="button" class="ui-icon-button ui-button--tertiary" aria-label="${esc(text)}" data-action="${action}" ${attrs}><img class="lt-icon" data-icon="${file}" src="${new URL(`./icons/${file}.svg`,import.meta.url)}" alt=""></button>`;
const toggle=m=>`<button type="button" class="ui-switch" role="switch" aria-label="${esc(m.name)}" aria-checked="${m.enabled}" ${toggleIntents.has(m.id)&&!toggleIntents.get(m.id).failed?'aria-busy="true"':''} ${initial.writeBlocked||initial.deletingIds?.includes(m.id)?'disabled':''} data-action="toggle" data-id="${esc(m.id)}"><span class="ui-switch__track"><span class="ui-switch__knob"></span></span></button>`;
const field=(label,key,value,type='text')=>`<label class="ui-field"><span class="ui-field__label">${label}</span><input class="ui-input" name="${key}" value="${esc(value)}" type="${type}" ${type==='number'?'min="0" max="10000" step="1"':''} required></label>`;
const select=(label,key,value,choices)=>`<label class="ui-field"><span class="ui-field__label">${label}</span><select class="ui-input" name="${key}">${Object.entries(choices).map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;
function remember(){const m=app.querySelector('.lt-main');if(m)scrolls[state.route+state.kind]=m.scrollTop;}
function go(route){remember();state.route=route;state.dialog=null;render();}
function toast(text){if(disposed)return;clearTimeout(toastTimer);app.querySelector('.wk-toast')?.remove();const p=app.ownerDocument.createElement('p');p.className='wk-toast';p.setAttribute('role','status');p.textContent=text;app.querySelector('.workshop')?.append(p);toastTimer=setTimeout(()=>p.remove(),1800);}
function root(){return `${initial.warning?`<p class="wk-intro" role="status">${esc(initial.warning)}</p><p class="wk-intro"><a href="${new URL('./assets/workshop-hide.regex.json',import.meta.url)}" download="兰台-隐藏工坊信息.json">下载隐藏正则</a> · <a href="${new URL('./assets/workshop-statusbar.regex.json',import.meta.url)}" download="兰台-时间状态栏美化.json">下载状态栏正则</a></p>`:''}<div class="wk-toolbar"><span class="lt-meta">${modules.filter(m=>m.kind===state.kind&&m.enabled).length} 条已启用</span>${btn('＋ 新建','new','','secondary')}</div>${Object.entries(scopes).map(([scope,label])=>{const rows=modules.filter(m=>m.kind===state.kind&&m.scope===scope);if(!rows.length)return '';const groupKey=state.kind+':'+scope;return `<details class="wk-group" data-scope="${scope}" data-group-key="${groupKey}" ${collapsed[groupKey]?'':'open'}><summary class="wk-group-title"><span class="wk-group-label">${label}</span><span class="lt-meta">${scope==='character'?esc(initial.characterName)+' · ':''}${rows.length} 条</span></summary><div class="wk-list">${rows.map(m=>`<article class="wk-row"><button type="button" class="wk-row-main" data-action="edit" data-id="${esc(m.id)}"><span class="wk-row-name">${esc(m.name)}</span></button><div class="wk-row-actions">${toggle(m)}</div><span class="lt-meta wk-row-meta">${m.role} · 深度 ${m.depth}${m.kind!=='prompt'?` · ${generationSources[m.generationSource??'story']}`:''}</span>${m.kind!=='prompt'?`<button type="button" class="wk-result-link" data-action="results" data-id="${esc(m.id)}" aria-label="查看${esc(m.name)}结果">查看结果<span aria-hidden="true">›</span></button>`:''}</article>`).join('')}</div></details>`;}).join('')}`;}
function editor(){const d=state.draft;return `<form id="rule-form" class="wk-form"><section class="wk-form-section">${field('名称','name',d.name)}${select('作用范围','scope',d.scope,initial.canUseCharacter?scopes:{global:scopes.global,chat:scopes.chat})}${d.kind!=='prompt'?select('生成来源','generationSource',d.generationSource??'story',generationSources):''}<div class="wk-pair">${select('发送角色','role',d.role,{system:'system',user:'user',assistant:'assistant'})}${field('注入深度','depth',d.depth,'number')}</div></section><section class="wk-form-section wk-form-content"><label class="ui-field"><span class="ui-field__label">${{prompt:'提示词内容',collect:'收集内容与要求',sync:'追踪内容与更新要求'}[d.kind]}</span><textarea class="lt-textarea lt-prompt-editor" name="content" required>${esc(d.content)}</textarea></label></section></form>`;}
function resultView(){const m=modules.find(m=>m.id===state.moduleId),rows=results[m.id]??[];if(!rows.length)return `<h2 class="wk-result-title">${esc(m.name)}</h2><div class="wk-empty">尚无结果</div>`;state.index=Math.min(state.index,rows.length-1);const r=rows[state.index];return `<section class="wk-results"><div class="wk-result-heading"><h2 class="wk-result-title">${esc(m.name)}</h2></div><article class="wk-result-panel"><div class="wk-result-meta"><span class="lt-meta">${m.kind==='sync'?'当前 · ':''}第 ${r.floor} 楼${r.edited?' · 已修改':''}</span><div>${btn('编辑','edit-result',`data-result="${esc(r.id)}"`)}${btn('删除','delete-result',`data-result="${esc(r.id)}"`)}</div></div><p class="wk-result">${esc(r.text)}</p></article>${m.kind==='sync'?`<div class="wk-history-list">${rows.slice(1).map((old,i)=>`<details class="wk-history"><summary>${i===0?'上一次':'前两次'} <span class="lt-meta">· 第 ${old.floor} 楼</span></summary><p class="wk-result">${esc(old.text)}</p></details>`).join('')}</div>`:''}</section>`;}
function resultFooter(){const m=modules.find(m=>m.id===state.moduleId),rows=results[state.moduleId]??[];return state.route==='results'&&m?.kind==='collect'&&rows.length?`<div class="wk-result-nav">${btn('上一条','prev',state.index===0?'disabled':'')}${btn(`目录 ${state.index+1} / ${rows.length}`,'directory',`aria-label="打开记录目录，当前第${state.index+1}条，共${rows.length}条"`)}${btn('下一条','next',state.index===rows.length-1?'disabled':'')}</div>`:'';}
function directoryMatches(){const q=state.query.trim().toLocaleLowerCase();return (results[state.moduleId]??[]).map((r,index)=>({r,index})).filter(({r})=>!q||(/^\d+$/.test(q)?r.floor===Number(q):r.text.toLocaleLowerCase().includes(q)));}
function directoryRows(){const matches=directoryMatches(),visible=matches.slice(0,state.directoryLimit);return `<p class="lt-meta" role="status">${state.query?`找到 ${matches.length} 条`:`共 ${matches.length} 条记录`}</p><div class="wk-directory-list">${visible.map(({r,index})=>`<button type="button" class="wk-directory-item" data-action="choose-record" data-result="${esc(r.id)}" ${index===state.index?'aria-current="true"':''}><span class="wk-directory-title">第 ${r.floor} 楼${index===state.index?' · 正在阅读':''}${r.edited?' · 已修改':''}</span><span class="wk-directory-preview">${esc(r.text.slice(0,100))}</span></button>`).join('')||'<p class="wk-empty">没有找到，换个楼层或词语试试</p>'}</div>${matches.length>visible.length?btn(`继续加载（已显示 ${visible.length} / ${matches.length}）`,'load-more','','secondary'):''}`;}
function directoryView(){const m=modules.find(m=>m.id===state.moduleId),rows=results[state.moduleId]??[];return `<section class="wk-directory"><h2 class="wk-result-title">${esc(m.name)}</h2><label class="ui-field"><span class="ui-field__label">找一条记录</span><input class="ui-input" type="search" maxlength="200" data-directory-search placeholder="输入楼层数字或正文词语" value="${esc(state.query)}"></label><div class="wk-directory-shortcuts">${btn('最早一条','first-record',rows.length?'':'disabled')}${btn('最新一条','last-record',rows.length?'':'disabled')}</div><div id="wk-directory-body">${directoryRows()}</div></section>`;}
function resultEditor(){return `<form id="result-form" class="wk-form"><p class="lt-meta">来源楼层 ${state.draft.floor}</p><label class="ui-field"><span class="ui-field__label">结果正文</span><textarea class="lt-textarea" name="text" required>${esc(state.draft.text)}</textarea></label></form>`;}
function render(){if(disposed)return;if(['results','directory','result-editor'].includes(state.route)&&!modules.some(m=>m.id===state.moduleId))state.route='root';state.theme=surfaceTheme(app);const focused=app.getRootNode().activeElement, focusAction=focused?.dataset?.action, focusKey=focused?.dataset?JSON.stringify({...focused.dataset}):null;if(state.closed){app.innerHTML=`<div class="wk-closed">${btn('打开工坊','reopen','','primary')}</div>`;return;}const rootPage=state.route==='root',edit=state.route==='editor'||state.route==='result-editor';const title=rootPage?'工坊':state.route==='editor'?(modules.some(m=>m.id===state.draft.id)?'编辑':'新建')+kinds[state.kind]:state.route==='result-editor'?'编辑结果':state.route==='directory'?'记录目录':'查看结果';const body=rootPage?root():state.route==='editor'?editor():state.route==='result-editor'?resultEditor():state.route==='directory'?directoryView():resultView();app.innerHTML=`<section class="lantai workshop ui-workspace ui-graphic-controls" data-ui-theme="${state.theme}"><header class="lt-header ui-header ${rootPage?'lt-header--root':'ui-header--centered'}">${rootPage?`<div class="lt-root-top"><h1 class="ui-page-title">工坊</h1>${icon('关闭兰台','close','close')}</div><nav class="ui-tablist" aria-label="功能分区">${Object.entries(kinds).filter(([key])=>availability()[key]).map(([k,v])=>btn(v,'tab',`data-kind="${k}" class="lt-type" ${k===state.kind?'aria-current="page"':''}` ).replace('class="ui-button ui-button--tertiary"','class="ui-button lt-type"').replace(' class="lt-type"','')).join('')}</nav>`:`${icon('返回','back','back')}<h1 class="ui-page-title">${title}</h1>${icon('关闭兰台','close','close')}`}</header><main class="lt-main ui-main" tabindex="-1">${lastError?`<p class="lt-error" role="alert">${esc(lastError)}</p>${btn('重新读取','reload')}`:''}${body}</main>${rootPage?`<footer class="lt-footer">${mainNavigation({policy:availability(),current:'workshop',actions:{workshop:'home'}})}</footer>`:edit?`<footer class="lt-footer"><div class="wk-editor-footer">${state.route==='editor'&&modules.some(m=>m.id===state.draft.id)?btn('删除','delete-module','','danger'):''}${btn('保存','save','','primary')}</div></footer>`:`<footer class="lt-footer${resultFooter()?' wk-reader-footer':''}">${resultFooter()}</footer>`}${state.dialog?`<div class="wk-dialog" role="dialog" aria-modal="true" aria-label="确认操作"><div class="wk-dialog-box"><p>${state.dialog.pending?'正在处理，请稍候…':state.dialog.text}</p><div class="wk-dialog-actions">${btn(state.dialog.cancelLabel??'取消','cancel-dialog',state.dialog.pending?'disabled':'')}${btn(state.dialog.pending?'处理中…':state.dialog.confirmLabel??'确认','confirm-dialog',state.dialog.pending?'disabled aria-busy="true"':'','primary')}</div></div></div>`:''}</section>`;if(state.dialog){for(const n of app.querySelectorAll('.lt-header,.lt-main,.lt-footer'))n.inert=true;app.querySelector('[data-action="cancel-dialog"]').focus({preventScroll:true});}else {app.querySelector('.lt-main').scrollTop=scrolls[state.route+state.kind]??0;if(focused&&app.contains?.(focused)===false&&focusAction){const target=[...app.querySelectorAll('[data-action]')].find(n=>JSON.stringify({...n.dataset})===focusKey);(target??app.querySelector('.lt-main')).focus({preventScroll:true});}}}
function readDraft(){const f=app.querySelector('form');if(!f)return;for(const [k,v] of new FormData(f))state.draft[k]=k==='depth'?Number(v):v;}
function dirty(){const f=app.querySelector('form');if(!f)return false;const current={...state.draft};for(const [k,v] of new FormData(f))current[k]=k==='depth'?Number(v):v;return JSON.stringify(current)!==draftBaseline;}
function confirm(text,fn,labels={}){readDraft();state.dialog={text,fn,...labels};render();}
function leave(fn){if(dirty())confirm('放弃未保存的修改？',fn,{cancelLabel:'继续编辑',confirmLabel:'放弃修改'});else fn();}
app.addEventListener('toggle',e=>{const group=e.target;if(group.matches?.('.wk-group')&&app.contains(group))collapsed[group.dataset.groupKey]=!group.open;},{capture:true,signal:lifetime.signal});
app.addEventListener('submit',e=>e.preventDefault(),{signal:lifetime.signal});
app.addEventListener('input',e=>{if(!e.target.matches?.('[data-directory-search]'))return;state.query=e.target.value;state.directoryLimit=20;app.querySelector('#wk-directory-body').innerHTML=directoryRows();},{signal:lifetime.signal});
function syncToggles(extra){
 const buttons=[...app.querySelectorAll('[data-action="toggle"]'),...(extra?[extra]:[])];
 for(const button of buttons){const module=modules.find(row=>row.id===button.dataset.id);if(!module)continue;
 button.setAttribute('aria-checked',String(module.enabled));
 if(toggleIntents.has(module.id)&&!toggleIntents.get(module.id).failed)button.setAttribute('aria-busy','true');else button.removeAttribute('aria-busy');}
 const count=app.querySelector('.wk-toolbar .lt-meta');if(count)count.textContent=modules.filter(row=>row.kind===state.kind&&row.enabled).length+' 条已启用';
}
async function changeToggle(b){
 if(disposed||acting||lastError||state.dialog)return;
 const id=b.dataset.id,module=modules.find(row=>row.id===id);if(!module)return;
 const intent={enabled:!module.enabled,version:++toggleVersion};toggleIntents.set(id,intent);module.enabled=intent.enabled;syncToggles(b);
 try{
   const value=await controller.toggle(id,intent.enabled);if(disposed)return;
   if(toggleIntents.get(id)!==intent)return;
   toggleIntents.delete(id);apply(controller.snapshot?.()??value);syncToggles(b);
 }catch(error){if(disposed)return;for(const pending of toggleIntents.values())pending.failed=true;initial.writeBlocked=true;remember();readDraft();lastError=error.message||'保存未确认，请重新读取';render();}
}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||disposed)return;const a=b.dataset.action,id=b.dataset.id;
if(a==='toggle')return changeToggle(b);
if(acting&&!['close','memory','time','benmo','settings','cancel-dialog','confirm-dialog'].includes(a))return;
let ownsAction=false;
try{
if(a==='reload'){acting=ownsAction=true;readDraft();const value=await controller.load({refresh:true});if(disposed)return;toggleIntents.clear();apply(value);render();return;}
if(a==='cancel-dialog'){if(state.dialog?.pending)return;state.dialog=null;render();return;}if(a==='confirm-dialog'){if(!state.dialog||state.dialog.pending)return;const dialog=state.dialog;acting=ownsAction=true;dialog.pending=true;render();await dialog.fn();if(disposed)return;if(state.dialog===dialog)state.dialog=null;render();return;}
if(a==='tab'){if(!availability()[b.dataset.kind])return;remember();state.kind=b.dataset.kind;state.route='root';render();}
if(a==='new'||a==='edit'){state.draft=a==='edit'?structuredClone(modules.find(m=>m.id===id)):make(crypto.randomUUID(),state.kind,'global','', '',true);state.draft.generationSource=state.draft.kind==='prompt'?'story':state.draft.generationSource??'story';draftBaseline=JSON.stringify(state.draft);go('editor');}
if(a==='results'){acting=ownsAction=true;apply(await controller.load());if(!modules.some(m=>m.id===id)){go('root');toast('模块已变化，请重新选择');return;}state.moduleId=id;state.index=0;state.query='';state.directoryLimit=20;scrolls['directory'+state.kind]=0;scrolls['results'+state.kind]=0;go('results');}
if(a==='directory')go('directory');
if(a==='load-more'){state.directoryLimit+=20;const top=app.querySelector('.lt-main').scrollTop;const oldCount=state.directoryLimit-20;app.querySelector('#wk-directory-body').innerHTML=directoryRows();const items=app.querySelectorAll('.wk-directory-item');items[oldCount]?.focus({preventScroll:true});app.querySelector('.lt-main').scrollTop=top;}
if(a==='choose-record'||a==='first-record'||a==='last-record'){const rows=results[state.moduleId]??[];state.index=a==='first-record'?0:a==='last-record'?rows.length-1:rows.findIndex(r=>r.id===b.dataset.result);scrolls['results'+state.kind]=0;go('results');}
if(a==='prev'||a==='next'){state.index+=a==='next'?1:-1;scrolls['results'+state.kind]=0;render();}
if(a==='edit-result'){acting=ownsAction=true;apply(await controller.load());const record=results[state.moduleId]?.find(r=>r.id===b.dataset.result);if(!record){state.index=0;go(modules.some(m=>m.id===state.moduleId)?'results':'root');toast('这条结果已变化，请重新选择');return;}state.draft=structuredClone(record);draftBaseline=JSON.stringify(state.draft);go('result-editor');}
if(a==='delete-result')confirm('删除这条结果？',async()=>{acting=ownsAction=true;apply(await controller.deleteResult(b.dataset.result));state.index=0;render();toast('已删除');});
if(a==='delete-module')confirm('删除这个模块？',async()=>{acting=ownsAction=true;apply(await controller.deleteModule(state.draft.id));go('root');});
if(a==='save'){const f=app.querySelector('form');if(!f.reportValidity())return;readDraft();
 if(state.route==='editor'){
   acting=ownsAction=true;
   const submitted=JSON.stringify(state.draft);
   const value=await controller.saveModule(state.draft);if(disposed)return;
   readDraft();const editedWhileSaving=JSON.stringify(state.draft)!==submitted;
   apply(value);draftBaseline=submitted;
   if(!editedWhileSaving)go('root');
   toast(editedWhileSaving?'已保存提交内容；新修改尚未保存':'已保存');return;
 }
 acting=ownsAction=true;apply(await controller.editResult(state.draft.id,state.draft.text));go('results');toast('已保存');
}
if(a==='back')leave(()=>go(['result-editor','directory'].includes(state.route)?'results':'root'));
if(a==='close')leave(()=>controller.close());
if(a==='memory'||a==='time'||a==='benmo'||a==='settings')leave(()=>controller[a]());if(a==='home')go('root');
}catch(error){if(!disposed){readDraft();state.dialog=null;initial.writeBlocked=controller.snapshot?.().writeBlocked??true;lastError=error.message||'操作未完成，请重试';remember();render();}}finally{if(ownsAction)acting=false;}},{signal:lifetime.signal});

app.addEventListener('keydown',event=>{
 if(!state.dialog)return;
 if(event.key==='Escape'){if(state.dialog.pending){event.preventDefault();event.stopPropagation();return;}event.preventDefault();event.stopPropagation();state.dialog=null;render();return;}
 if(event.key==='Tab'){const buttons=[...app.querySelectorAll('.wk-dialog button')];if(!buttons.length)return;event.preventDefault();const index=buttons.indexOf(app.getRootNode().activeElement);buttons[(index+(event.shiftKey?-1:1)+buttons.length)%buttons.length].focus();}
},{signal:lifetime.signal});
render();
return {refreshAvailability(){remember();readDraft();render();},invalidate(message){readDraft();lastError=message;render();},dispose(){disposed=true;lifetime.abort();clearTimeout(toastTimer);app.innerHTML='';},back(){if(acting)return;leave(()=>state.route==='root'?controller.memory():go(['result-editor','directory'].includes(state.route)?'results':'root'));},blocking(){return acting||toggleIntents.size>0||dirty()||!!state.dialog;},suspend(){app.inert=true;},resume(){app.inert=false;if(!availability()[state.kind]){state.kind=Object.keys(kinds).find(key=>availability()[key])??'prompt';state.route='root';}state.theme=surfaceTheme(app);render();}};
}
